for (const [file, map] of Object.entries(T)) {
  const raw = execSync(`git show HEAD:prompt/${file}`, { encoding: 'utf8' });
  const crlf = raw.includes('\r\n');
  const lines = raw.split(/\r?\n/);
  const hadTrailingNewline = /(?:\r?\n)$/.test(raw);
  const out = lines.map((l, idx) => {
    const n = idx + 1;
    if (map[n] !== undefined) {
      if (!cjk.test(l)) {
        throw new Error(`${file} L${n} has a translation entry but contains NO Chinese: ${JSON.stringify(l)}`);
      }
      return map[n];
    }
    return l;
  });
  // sanity: ensure every CJK line in original has a translation
  lines.forEach((l, idx) => {
    if (cjk.test(l) && map[idx + 1] === undefined) {
      throw new Error(`${file} L${idx + 1} contains Chinese but has NO translation: ${JSON.stringify(l)}`);
    }
  });
  let text = out.join('\n');
  // split(/\r?\n/) already preserves a trailing empty element when the raw
  // text ends with a newline, so out.join('\n') reproduces the original
  // trailing-newline state exactly. Do NOT append another newline here.
  if (crlf) text = text.replace(/\n/g, '\r\n');
  fs.writeFileSync(`prompt/${file}`, text, 'utf8');
  console.log(`wrote ${file}: ${out.length} lines, crlf=${crlf}, trailingNL=${hadTrailingNewline}`);
}